/**
 * Adapts a bridge entry to the WaSOS message format.
 *
 * Sets msg.metadata = entry.metadata — the two are the same object from here on.
 * WaSOS does not support attachments via API, so files is always empty.
 * Receiver text patching happens downstream in POST to WaSOS chat.
 */
const entry = msg.entry;
const source = entry.metadata.source;
const utils = global.get("utils");

msg.metadata = entry.metadata;
msg.payload = {
    content: entry.text,
    callsign: `${utils.build_callsign(source)} ${entry.author}`,
    isLocation: false,
    replyMessageId: null,
    files: []
};

return msg;

/**
 * Adapts a bridge entry to the Rayvn log entry format.
 *
 * Sets msg.metadata = entry.metadata — the two are the same object from here on.
 * File upload is handled downstream in Handle Rayvn files upload,
 * which reads files from metadata.files.items.
 */
const entry = msg.entry;
const source = entry.metadata.source;
const utils = global.get("utils");

msg.metadata = entry.metadata;
msg.payload = {
    text: `${utils.build_callsign(source)} ${entry.author}: ${entry.text || ""}`,
    keyEvent: false,
    releasedInfo: false,
    loggedByFullName: `${utils.build_callsign(source)} ${entry.author}`,
    labels: []
};

return msg;
